var i=`0485-manakish`;var t=`world-0485`;var n=`LB`;var o=`western-asia`;var r=8;var s=94;var l={en:`Manakish`,ua:`Манакиш`};var d={en:`A traditional dish from Lebanon, centered on all-purpose flour, instant yeast. A measured home-kitchen version organized by cooking step. Za’atar is approximated using dried thyme and sesame added at serving; the traditional spice blend is not cataloged.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: пшеничне борошно універсальне, інстантні дріжджі. Домашній варіант із кількостями продуктів за етапами приготування. Затар наближено відтворено сушеним чебрецем і кунжутом, адже готової традиційної суміші немає в каталозі.`};var u=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`water`,260,`ml`],[`instant-yeast`,6,`g`],[`extra-virgin-olive-oil`,40,`ml`],[`table-salt`,7,`g`]]},{en:`Mix dried thyme, olive oil and optionally sesame into a fragrant home-style za’atar topping.`,ua:`Змішайте сухий чебрець з оливковою олією і, за бажанням, кунжутом, домашня начинка за мотивами затару.`,t:[`mixing`],m:5,i:[[`dried-thyme`,80,`g`],[`extra-virgin-olive-oil`,80,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 14 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 14 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:14,i:[]}];var g={slug:i,id:t,country:`LB`,region:o,servings:8,minutes:94,title:l,text:d,steps:u};export{n as country,g as default,t as id,s as minutes,o as region,r as servings,i as slug,u as steps,d as text,l as title};